// ─── File: SpaceBasedDemo.java ───
// Space-based architecture: orders served from an in-memory grid, DB flushed async.
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class SpaceBasedDemo {
    private static final Logger log = Logger.getLogger("Trading");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        InMemoryDataGrid grid = new InMemoryDataGrid();     // the "space"
        ProcessingUnit unit = new ProcessingUnit(grid);     // logic + in-memory data
        DataWriter writer = new DataWriter(grid);           // async DB flush
        writer.start();

        log.info("--- market-open burst: 1000 orders served from memory ---");
        long t0 = System.nanoTime();
        for (int i = 1; i <= 1000; i++) {
            unit.placeOrder(new Order("ORD-" + i, "SAV2001", "RELIANCE", 10,
                    new BigDecimal("2450.50")));
        }
        long micros = (System.nanoTime() - t0) / 1000;
        log.info(() -> "Placed 1000 orders in " + micros + " microseconds (memory, no DB wait)");
        log.info(() -> "Grid holds " + grid.size() + " orders in memory");

        Thread.sleep(600);                                  // let the writer flush
        log.info(() -> "DB persisted " + writer.persistedCount() + " orders asynchronously");
        writer.stop();
    }
}

// ─── model/Order.java ───
class Order {
    final String orderId, accountId, symbol; final int quantity; final BigDecimal price;
    Order(String orderId, String accountId, String symbol, int quantity, BigDecimal price) {
            this.orderId = orderId;
            this.accountId = accountId
            this.symbol = symbol;
        this.quantity = quantity; this.price = price;
    }
}

// ─── grid/InMemoryDataGrid.java (stand-in for Hazelcast/Ignite) ───
class InMemoryDataGrid {
    // Partitioned+replicated in real grids; here a concurrent map + flush queue.
    private final ConcurrentMap<String, Order> space = new ConcurrentHashMap<>();
    private final BlockingQueue<Order> flushQueue = new LinkedBlockingQueue<>();
    void put(Order o) { space.put(o.orderId, o); flushQueue.add(o); } // write-behind
    Order get(String id) { return space.get(id); }                    // read from memory
    int size() { return space.size(); }
    Order pollForFlush(long timeoutMs) throws InterruptedException {
        return flushQueue.poll(timeoutMs, TimeUnit.MILLISECONDS);
    }
}

// ─── unit/ProcessingUnit.java (business logic + in-memory data, NO DB on hot path) ───
class ProcessingUnit {
    private final InMemoryDataGrid grid;
    ProcessingUnit(InMemoryDataGrid grid) { this.grid = grid; }
    void placeOrder(Order order) {
        // Validate + accept entirely against in-memory grid — microsecond latency.
        grid.put(order);
    }
    Order lookup(String orderId) { return grid.get(orderId); }
}

// ─── writer/DataWriter.java (async: drains the grid's flush queue to the DB) ───
class DataWriter {
    private static final Logger log = Logger.getLogger("Trading");
    private final InMemoryDataGrid grid;
    private volatile boolean running = false;
    private int persisted = 0;
    private Thread thread;
    DataWriter(InMemoryDataGrid grid) { this.grid = grid; }
    void start() {
        running = true;
        thread = new Thread(this::loop, "data-writer");
        thread.start();
    }
    private void loop() {
        try {
            while (running) {
                Order o = grid.pollForFlush(100);
                if (o != null) {
                    persisted++;                 // in prod: batched JDBC insert
                }
            }
        } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }
    int persistedCount() { return persisted; }
        void stop() { running = false;
        if (thread != null) thread.interrupt(); }
}

